mkdir -p "${ROOT}/submodules/hal-common"
mkdir -p "${ROOT}/submodules/hal-common/src"
mkdir -p "${ROOT}/submodules/hal-common/tests"
mkdir -p "${ROOT}/submodules/llm-gateway"
mkdir -p "${ROOT}/submodules/llm-gateway/certs"
mkdir -p "${ROOT}/submodules/llm-gateway/llm_gateway"
mkdir -p "${ROOT}/submodules/llm-gateway/tests"
mkdir -p "${ROOT}/submodules/rag-core"
mkdir -p "${ROOT}/submodules/rag-core/rag_core"
mkdir -p "${ROOT}/submodules/rag-core/rag_core/ingestion"
mkdir -p "${ROOT}/submodules/rag-core/rag_core/kb"
mkdir -p "${ROOT}/submodules/rag-core/rag_core/prompts"
mkdir -p "${ROOT}/submodules/rag-core/rag_core/retriever"
