# =============================================================================
# ZT-AI-CORE v2.4 — Security scanning (чек-лист §5: trivy, cargo-audit,
# bandit, semgrep + встроенный сканер + reproducible builds аудит).
# =============================================================================
name: Security Scan

on:
  push:
    branches: [main]
  pull_request:
    branches: [main]
  schedule:
    - cron: "0 3 * * 1"   # еженедельно, понедельник 03:00 UTC

permissions:
  contents: read
  security-events: write

jobs:
  internal-scanner:
    name: Встроенный сканер (секреты, политика SECCOMP, заглушки)
    runs-on: ubuntu-22.04
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-python@v5
        with:
          python-version: "3.11"
      - run: pip install blake3 grpcio-tools
      - run: python3 tools/security_scan.py

  trivy:
    name: Trivy (HIGH/CRITICAL)
    runs-on: ubuntu-22.04
    steps:
      - uses: actions/checkout@v4
      - name: Trivy filesystem scan
        uses: aquasecurity/trivy-action@0.28.0
        with:
          scan-type: fs
          scan-ref: .
          severity: HIGH,CRITICAL
          exit-code: "1"
          ignore-unfixed: true
        continue-on-error: false

  rust-audit:
    name: cargo-audit (RustSec)
    runs-on: ubuntu-22.04
    strategy:
      matrix:
        crate: [hal-common, fsm-engine, worm-audit]
    steps:
      - uses: actions/checkout@v4
      - uses: dtolnay/rust-toolchain@stable
      - name: Install cargo-audit
        run: cargo install cargo-audit --locked
      - name: Audit
        working-directory: submodules/${{ matrix.crate }}
        run: cargo audit

  bandit:
    name: Bandit (Python SAST)
    runs-on: ubuntu-22.04
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-python@v5
        with:
          python-version: "3.11"
      - run: pip install bandit
      - name: Bandit
        run: |
          bandit -r submodules/llm-gateway/llm_gateway \
                   submodules/rag-core/rag_core \
                   submodules/t8-sandbox/seccomp \
                   submodules/t8-sandbox/ztbootstrap \
                   submodules/t8-sandbox/grpc_client \
                   submodules/t8-sandbox/bootstrap.py \
            -x '*/tests/*' --exit-zero || true
          bandit -r submodules/llm-gateway/llm_gateway \
                   submodules/rag-core/rag_core \
            -x '*/tests/*' -ll

  semgrep:
    name: Semgrep
    runs-on: ubuntu-22.04
    container:
      image: semgrep/semgrep
    steps:
      - uses: actions/checkout@v4
      - run: semgrep ci --config=auto submodules/ || semgrep --config=auto submodules/

  reproducible-check:
    name: Reproducible builds (F-I-05)
    runs-on: ubuntu-22.04
    steps:
      - uses: actions/checkout@v4
      - uses: dtolnay/rust-toolchain@stable
      - name: Два независимых билда worm-audit → одинаковые хэши
        run: |
          cd submodules/worm-audit
          cargo build --release
          H1=$(sha256sum target/release/zt-worm-audit | cut -d' ' -f1)
          touch src/lib.rs src/main.rs
          cargo build --release
          H2=$(sha256sum target/release/zt-worm-audit | cut -d' ' -f1)
          echo "build1=$H1"; echo "build2=$H2"
          if [ "$H1" != "$H2" ]; then
            echo "::warning::Бинари различаются (timestamp embedding) — используйте SOURCE_DATE_EPOCH для полной воспроизводимости"
          fi
