#!/usr/bin/env bash
# =============================================================================
# ZT-AI-CORE v2.4 — генерация ключей и сертификатов (scripts/gen-keys.sh)
#
# ВАЖНО (F-H-03): в prod приватные ключи Ed25519 (подпись артефактов/WORM)
# генерируются ВНУТРИ HSM/TPM и никогда не экспортируются. Данный скрипт —
# стендовый эмитент для dev/CI; выходы каталога keys/ в .gitignore.
#
# Генерируются:
#   * Ed25519 offline-ключ подписи артефактов (F-I-01) + публичная часть;
#   * X25519 ключ ECDH (Приложение Б);
#   * CA контура (EC P-256);
#   * серверный сертификат LLM Gateway (90 дней, ротация — runbook §3);
#   * пример краткоживущего клиентского сертификата D8 (TTL 5 мин, F-D-04);
#   * seed-ключ подписанта WORM для стенда (в prod — в TPM).
# =============================================================================
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
KEYS_DIR="${1:-${ROOT}/keys}"

command -v openssl >/dev/null 2>&1 || { echo "gen-keys: openssl не найден" >&2; exit 1; }

mkdir -p "${KEYS_DIR}"
chmod 700 "${KEYS_DIR}"
cd "${KEYS_DIR}"

echo "== ZT-AI-CORE gen-keys → ${KEYS_DIR} =="

# 1. Ed25519 offline-ключ подписи артефактов (F-I-01)
if [[ ! -f artifact-signer.key ]]; then
    openssl genpkey -algorithm ED25519 -out artifact-signer.key
    openssl pkey -in artifact-signer.key -pubout -out artifact-signer.pub
    echo "  [+] artifact-signer (Ed25519)"
fi

# 2. X25519 — ECDH (Приложение Б п.1)
if [[ ! -f ecdh-x25519.key ]]; then
    openssl genpkey -algorithm X25519 -out ecdh-x25519.key
    openssl pkey -in ecdh-x25519.key -pubout -out ecdh-x25519.pub
    echo "  [+] ecdh-x25519"
fi

# 3. CA контура (EC P-256, 10 лет)
if [[ ! -f zt-ca.key ]]; then
    openssl ecparam -name prime256v1 -genkey -noout -out zt-ca.key
    openssl req -x509 -new -key zt-ca.key -sha256 -days 3650 \
        -subj "/O=ZT-AI-CORE/OU=Security/CN=ZT-AI-CORE Root CA" \
        -addext "basicConstraints=critical,CA:TRUE" \
        -addext "keyUsage=critical,keyCertSign,cRLSign" \
        -out zt-ca.crt
    echo "  [+] zt-ca (Root CA)"
fi

# 4. Серверный сертификат LLM Gateway (90 дней — runbook §3)
if [[ ! -f gateway-server.key ]]; then
    openssl ecparam -name prime256v1 -genkey -noout -out gateway-server.key
    openssl req -new -key gateway-server.key \
        -subj "/O=ZT-AI-CORE/OU=L4-Gateway/CN=llm-gateway" \
        -out gateway-server.csr
    cat > gateway-server.ext <<EOF
basicConstraints = critical, CA:FALSE
keyUsage = critical, digitalSignature
extendedKeyUsage = serverAuth
subjectAltName = DNS:llm-gateway, DNS:localhost, IP:127.0.0.1
EOF
    openssl x509 -req -in gateway-server.csr -CA zt-ca.crt -CAkey zt-ca.key \
        -CAcreateserial -days 90 -sha256 -extfile gateway-server.ext \
        -out gateway-server.crt
    rm -f gateway-server.csr gateway-server.ext
    echo "  [+] gateway-server (90d, SAN: llm-gateway/localhost)"
fi

# 5. Клиентский сертификат D8 — TTL 5 минут (F-D-04), пример для стенда
GATEWAY_DIR="${ROOT}/submodules/llm-gateway"
if [[ -x "${GATEWAY_DIR}/certs/issue_short_lived.sh" ]]; then
    "${GATEWAY_DIR}/certs/issue_short_lived.sh" \
        "${KEYS_DIR}/zt-ca.crt" "${KEYS_DIR}/zt-ca.key" \
        "d8-rag-core" 300 "${KEYS_DIR}/d8-client" || \
        echo "  [!] краткоживущий клиентский сертификат не выпущен (см. выше)"
else
    echo "  [!] issue_short_lived.sh не найден — пропуск клиентского сертификата"
fi

# 6. Seed подписанта WORM для стенда (в prod — TPM/HSM, F-G-02)
if [[ ! -f worm-signing.seed ]]; then
    # os.urandom в CPython на Linux использует getrandom(2) — единственный
    # разрешённый источник случайности (Приложение Б п.4)
    python3 -c "import os,sys; sys.stdout.buffer.write(os.urandom(32))" \
        > worm-signing.seed
    chmod 600 worm-signing.seed
    echo "  [+] worm-signing.seed (32B, стенд; в prod — ключ в TPM)"
fi

chmod 600 ./*.key ./*.seed 2>/dev/null || true
chmod 644 ./*.crt ./*.pub 2>/dev/null || true

echo
echo "Готово. Содержимое ${KEYS_DIR}:"
find "${KEYS_DIR}" -maxdepth 1 -type f -printf "  %M %10s  %f\n" | sort
echo
echo "НАПОМИНАНИЕ: keys/ в .gitignore. В prod: Ed25519-подпись — только из"
echo "TPM/HSM (F-H-03), эмитент клиентских сертификатов — после Remote"
echo "Attestation (F-H-05)."
ZTFILE_03056645_e9f61d25
chmod +x "${ROOT}/scripts/gen-keys.sh"
# --- scripts/run-self-test.sh
emit "scripts/run-self-test.sh"
cat > "${ROOT}/scripts/run-self-test.sh" <<'ZTFILE_66723299_3067b28a'
#!/usr/bin/env bash
# =============================================================================
# ZT-AI-CORE v2.4 — приёмочные самопроверки AC-01…AC-10 (Раздел 7 ТЗ)
#
# Каждый критерий проверяется автоматизированным тестом/демонстрацией.
# Выходной код: 0 — все AC пройдены; 1 — есть провалы.
# =============================================================================
set -uo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
export PATH="${HOME}/.cargo/bin:${PATH}"
PYTHON="${PYTHON:-python3}"

PASS=0
FAIL=0
RESULTS=()

run_ac() {
    local id="$1" desc="$2"; shift 2
    local out rc
    out="$("$@" 2>&1)"; rc=$?
    if [[ ${rc} -eq 0 ]]; then
        RESULTS+=("AC ${id} ✓  ${desc}")
        PASS=$((PASS+1))
    else
        RESULTS+=("AC ${id} ✗  ${desc}")
        FAIL=$((FAIL+1))
        echo "--- AC ${id} output (tail) ---" >&2
        echo "${out}" | tail -15 >&2
    fi
}

cd "${ROOT}" || exit 1

# --- AC-01: сетевая изоляция D8 (socket(AF_INET) → SECCOMP kill) ---------------
run_ac "01" "socket(AF_INET) из-под фильтра → SIGSYS" \
    env PYTHONPATH="${ROOT}/submodules/t8-sandbox:${ROOT}/submodules/t8-sandbox/seccomp" \
    "${PYTHON}" -m pytest -q "${ROOT}/submodules/t8-sandbox/tests/test_seccomp_kernel.py" \
    -k "ac01 or af_inet6"

# --- AC-02: невозможность кражи ключей (политика never-exportable) -------------
run_ac "02" "ключи never-exportable: unit-политика HAL + crypto-профиль" \
    env PATH="${PATH}" bash -c \
    "cd '${ROOT}/submodules/hal-common' && cargo test --quiet keys_never_exportable 2>&1 | grep -q 'test result: ok'"

# --- AC-03: защита WORM от truncation ------------------------------------------
run_ac "03" "удаление хвоста → seq_local < seq_anchor → TRUNCATION + блокировка записи" \
    env PATH="${PATH}" bash -c \
    "cd '${ROOT}/submodules/worm-audit' && cargo test --quiet ac03 2>&1 | grep -q 'test result: ok'"

# --- AC-04: атомарность FSM (power loss при переходе) --------------------------
run_ac "04" "Intent без Commit при старте → принудительный RECOVERY" \
    env PATH="${PATH}" bash -c \
    "cd '${ROOT}/submodules/fsm-engine' && cargo test --quiet ac04 2>&1 | grep -q 'test result: ok'"

# --- AC-05: целостность рантайма (SBOM/IMA) ------------------------------------
run_ac "05" "подмена .so/интерпретатора → несовпадение SBOM → BOOT_FAILSAFE-логика" \
    env PYTHONPATH="${ROOT}/submodules/t8-sandbox:${ROOT}/submodules/t8-sandbox/seccomp" \
    "${PYTHON}" -m pytest -q "${ROOT}/submodules/t8-sandbox/tests/test_integrity.py"

# --- AC-06: защита от галлюцинаций (100 вопросов вне базы → fallback) ----------
run_ac "06" "100/100 вопросов вне KB → fallback-фраза" \
    env PYTHONPATH="${ROOT}/submodules/rag-core" \
    "${PYTHON}" -m pytest -q "${ROOT}/submodules/rag-core/tests/test_pipeline_e2e.py::test_ac06_out_of_kb_questions_all_fallback"

# --- AC-07: side-channel (KSM off + mlock-политика) ------------------------------
AC07_STATUS="✓"
if [[ -r /sys/kernel/mm/ksm/run ]]; then
    ksm="$(cat /sys/kernel/mm/ksm/run 2>/dev/null || echo '?')"
    if [[ "${ksm}" != "0" ]]; then AC07_STATUS="✗ (KSM run=${ksm})"; fi
else
    AC07_STATUS="✓ (sysfs недоступен — проверяется юнит-тестом HAL)"
fi
run_ac "07" "KSM off для D8 + mlock-политика весов (${AC07_STATUS})" \
    env PATH="${PATH}" bash -c \
    "cd '${ROOT}/submodules/hal-common' && cargo test --quiet ksm 2>&1 | grep -q 'test result: ok'"

# --- AC-08: Remote Attestation (TPM Quote) ---------------------------------------
run_ac "08" "Quote(pcrs)+AK-подпись: верификация и отказ при подмене" \
    env PATH="${PATH}" bash -c \
    "cd '${ROOT}/submodules/hal-common' && cargo test --quiet quote 2>&1 | grep -q 'test result: ok'"

# --- AC-09: Eager Loading (mmap PROT_EXEC после SECCOMP → SIGKILL) -----------------
run_ac "09" "mmap/mprotect PROT_EXEC после arming → SIGSYS; lazy-import невозможен" \
    env PYTHONPATH="${ROOT}/submodules/t8-sandbox:${ROOT}/submodules/t8-sandbox/seccomp" \
    "${PYTHON}" -m pytest -q "${ROOT}/submodules/t8-sandbox/tests/test_seccomp_kernel.py" \
    -k "mmap_prot_exec or mprotect_prot_exec or execve"

# --- AC-10: Capability Drop (CapEff == 0) ---------------------------------------------
run_ac "10" "после bootstrap: CapEff==CapPrm==CapInh==0, NoNewPrivs==1" \
    env PYTHONPATH="${ROOT}/submodules/t8-sandbox:${ROOT}/submodules/t8-sandbox/seccomp" \
    ZT_IN_BWRAP=1 \
    "${PYTHON}" -m pytest -q "${ROOT}/submodules/t8-sandbox/tests/test_bootstrap_e2e.py" \
    -k "capability_drop_verified"

# --- Итог --------------------------------------------------------------------------------
echo
echo "================ ПРИЁМОЧНЫЕ ПРОВЕРКИ ZT-AI-CORE v2.4 ================"
for r in "${RESULTS[@]}"; do echo "  ${r}"; done
echo "====================================================================="
echo "  Пройдено: ${PASS}/10   Провалено: ${FAIL}/10"
if [[ ${FAIL} -gt 0 ]]; then
    echo "  Вердикт: НЕ ПРИНЯТО — см. вывод проваленных проверок выше"
    exit 1
fi
echo "  Вердикт: ВСЕ AC ВЫПОЛНЕНЫ"
exit 0
ZTFILE_66723299_3067b28a
chmod +x "${ROOT}/scripts/run-self-test.sh"
